-- Rollback de 30_taxonomia_sectorial.sql. Sólo elimina conceptos sin valores asociados.
START TRANSACTION;
DELETE t FROM taxonomia_concepto t LEFT JOIN partida_contable_valor p ON p.concepto_estandar_id=t.id WHERE t.concepto_estandar IN ('PRESTAMOS_BRUTOS','PROVISION_INSOLVENCIAS','DEPOSITOS_CLIENTES','FINANCIACION_MAYORISTA','OTROS_ACTIVOS_FINANCIEROS','CET1','ACTIVOS_PONDERADOS_RIESGO','INVERSIONES_SEGUROS','PASIVO_CONTRATOS_SEGURO','INGRESO_SEGUROS','GASTO_SERVICIO_SEGUROS','REQUISITO_SOLVENCIA','PROPIEDADES_INVERSION','INGRESOS_ARRENDAMIENTO','BASE_ACTIVOS_REGULADOS','INMOVILIZADO_REGULADO','GASTO_I_D','OBLIGACIONES_DESEMPENO_PENDIENTES','RESERVAS_PROBADAS','ACTIVOS_AGOTABLES','AGOTAMIENTO','PASIVO_IMPUESTO_CORRIENTE','ACTIVO_IMPUESTO_CORRIENTE','ACTIVO_IMPUESTO_DIFERIDO','PASIVO_IMPUESTO_DIFERIDO') AND p.id IS NULL;
SELECT concepto_estandar AS conservado_por_tener_datos FROM taxonomia_concepto WHERE concepto_estandar IN ('PRESTAMOS_BRUTOS','PROVISION_INSOLVENCIAS','DEPOSITOS_CLIENTES','FINANCIACION_MAYORISTA','OTROS_ACTIVOS_FINANCIEROS','CET1','ACTIVOS_PONDERADOS_RIESGO','INVERSIONES_SEGUROS','PASIVO_CONTRATOS_SEGURO','INGRESO_SEGUROS','GASTO_SERVICIO_SEGUROS','REQUISITO_SOLVENCIA','PROPIEDADES_INVERSION','INGRESOS_ARRENDAMIENTO','BASE_ACTIVOS_REGULADOS','INMOVILIZADO_REGULADO','GASTO_I_D','OBLIGACIONES_DESEMPENO_PENDIENTES','RESERVAS_PROBADAS','ACTIVOS_AGOTABLES','AGOTAMIENTO','PASIVO_IMPUESTO_CORRIENTE','ACTIVO_IMPUESTO_CORRIENTE','ACTIVO_IMPUESTO_DIFERIDO','PASIVO_IMPUESTO_DIFERIDO');
COMMIT;
